files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  color: var(--vt-ink);
  background-color: var(--vt-surface);
  scroll-behavior: smooth;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s ease;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.05);
  padding: 1rem 0;
}

.navIn {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: inline-block;
}

.brand {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--vt-accent);
}

.navLinks {
  display: flex;
  gap: 1.5rem;
  align-items: center;
}

.navLinks a {
  font-weight: 600;
  font-size: 1rem;
  color: var(--vt-ink-soft);
  padding: 0.5rem 0;
}

.navLinks a:hover {
  color: var(--vt-ink);
}

.hero {
  position: relative;
  overflow: hidden;
  height: 580px;
}

.heroSlides {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
  scrollbar-width: none;
}

.heroSlides::-webkit-scrollbar {
  display: none;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  height: 100%;
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  width: 50%;
  z-index: 2;
}

.heroTitle {
  font-size: 48px;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 0.5rem;
  color: var(--vt-ink);
}

.heroWord {
  color: var(--vt-accent);
}

.heroSub {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  position: relative;
  overflow: hidden;
}

.customLink::before {
  content: attr(data-hover);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--vt-line);
  color: var(--vt-accent);
  text-align: center;
  transition: top 0.3s;
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  font-size: 1.1rem;
}

.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 15px;
}

.aboutRow {
  display: flex;
  align-items: center;
  gap: 3rem;
}

.aboutColText {
  flex: 1;
}

.aboutColImage {
  flex: 0 0 40%;
  max-width: 40%;
}

.aboutImage {
  width: 100%;
  height: auto;
  border-radius: 0.25rem;
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.1);
}

.sectionTitle {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 2rem;
  color: var(--vt-ink);
}

.gallery {
  background: var(--vt-surface-2);
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryItem {
  flex: 1;
  min-width: 0;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

.timelineSection {
  position: relative;
  padding-bottom: 5rem;
}

.timeline {
  position: relative;
  padding-top: 1rem;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  transform: translateX(-50%);
}

.timelineNodes {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  margin-bottom: 2rem;
}

.timelineContent {
  flex: 1;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1.5rem rgba(0,0,0,0.08);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
}

.timelineTitle {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  font-size: 1.25rem;
}

.timelineText {
  color: var(--vt-ink-soft);
  padding: 10px 30px;
  font-size: 1rem;
  font-weight: 300;
}

.timelineIcons {
  width: 80px;
  flex: 0 0 80px;
  text-align: center;
  position: relative;
  z-index: 10;
  margin: 0 1rem;
}

.timelineIcons::before {
  content: "";
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.175);
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
}

.timelineIcon {
  position: relative;
  z-index: 5;
  color: var(--vt-accent);
  font-size: 2rem;
  line-height: 80px;
}

.timelineDate {
  flex: 1;
  color: var(--vt-ink-soft);
  padding: 1.5rem 0;
  font-size: 1rem;
}

.timelineNodes.odd .timelineDate {
  order: 1;
  text-align: left;
}

.timelineNodes.odd .timelineIcons {
  order: 2;
}

.timelineNodes.odd .timelineContent {
  order: 3;
}

.timelineNodes.even .timelineContent {
  order: 1;
}

.timelineNodes.even .timelineIcons {
  order: 2;
}

.timelineNodes.even .timelineDate {
  order: 3;
  text-align: right;
}

.footer {
  background: var(--vt-surface-2);
  padding: 5rem 0;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerCol {
  flex: 1;
  min-width: 250px;
}

.footerTitle {
  color: var(--vt-ink);
  font-size: 1.25rem;
  margin-bottom: 1.5rem;
}

.hoursText {
  white-space: pre-line;
  color: var(--vt-ink-soft);
  font-size: 1rem;
  line-height: 1.6;
}

.footerBottom {
  margin-top: 3rem;
  text-align: center;
}

.copyrightText {
  color: var(--vt-ink-soft);
  font-size: 0.9rem;
}

@media (max-width: 991px) {
  .hero {
    height: auto;
  }
  .heroText {
    position: relative;
    bottom: auto;
    right: auto;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
  }
  .heroSlides {
    height: 400px;
  }
  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }
  .aboutRow {
    flex-direction: column;
  }
  .aboutColImage {
    flex: 0 0 100%;
    max-width: 100%;
  }
  .timelineNodes {
    flex-direction: column;
    align-items: flex-start;
  }
  .timelineNodes.odd .timelineDate,
  .timelineNodes.even .timelineDate {
    order: 0;
    text-align: left;
    width: 100%;
    padding: 0.5rem 0;
  }
  .timelineNodes.odd .timelineIcons,
  .timelineNodes.even .timelineIcons {
    order: 0;
    margin-left: 0;
    margin-bottom: 1rem;
  }
  .timelineNodes.odd .timelineContent,
  .timelineNodes.even .timelineContent {
    order: 0;
    width: 100%;
  }
  .timeline::before {
    left: 33px;
    top: 60px;
    height: 90%;
  }
  .timelineIcons {
    position: absolute;
    left: 0;
    top: 60px;
  }
}

@media (max-width: 767px) {
  .navLinks {
    display: none;
  }
  .heroTitle {
    font-size: 38px;
  }
  .heroText {
    padding: 1rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .heroSlides {
    scroll-behavior: auto;
  }
}
